import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiCodex","description":"","frontmatter":{},"headers":[],"relativePath":"modules/codex/index.md","filePath":"modules/codex/index.md","lastUpdated":0}`),a={name:`modules/codex/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakicodex" tabindex="-1">EmakiCodex <a class="header-anchor" href="#emakicodex" aria-label="Permalink to “EmakiCodex”">​</a></h1><p>EmakiCodex 同时包含两套独立的图鉴模型：<code>advancements/*.yml</code> 定义并注册原版 Advancement 页面与节点；<code>codex/*.yml</code> 定义分类、条目、解锁条件和奖励，由独立的分类条目 GUI 展示。两套模型可以通过 Advancement 解锁关联，但 <code>page_id</code> 与 <code>category_id</code> 不互相替代。</p><p>安装 PacketEvents 时，EmakiCodex 会额外启用客户端成就树坐标注入与在线玩家重推能力；未安装 PacketEvents 时，原版成就仍会注册，但节点位置由客户端按 parent 树自动排布，在线玩家可能需要重新登录才能看到刚重载后的成就树变化。分类条目 GUI 不依赖 PacketEvents，但其奖励动作仍通过 CoreLib 执行，属性奖励由当前配置实时推导。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本（POM/runtime）</td><td><code>1.1.0</code></td></tr><tr><td>API Jar</td><td><code>emaki-codex-api-1.1.0.jar</code></td></tr><tr><td>默认配置结构版本</td><td><code>1.1.0</code></td></tr><tr><td>主类</td><td><code>emaki.jiuwu.craft.codex.EmakiCodexPlugin</code></td></tr><tr><td>主命令</td><td><code>/codex</code></td></tr><tr><td>别名</td><td><code>/ecodex</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>PlaceholderAPI、PacketEvents、MythicMobs</td></tr><tr><td>最低服务端</td><td>Paper 1.21.8+（<code>api-version: 1.21.8</code>，<code>folia-supported: true</code>）</td></tr><tr><td>Java</td><td>Java 25</td></tr><tr><td>主要权限</td><td><code>emakicodex.use</code>（默认 true）、<code>emakicodex.reload</code>（op）、<code>emakicodex.debug</code>（op）、<code>emakicodex.admin</code>（op）</td></tr></tbody></table><p>POM/runtime/API 与默认 <code>config.yml</code> 的版本值是 <code>1.1.0</code>；源码内部的 <code>AppConfig.CURRENT_VERSION = &quot;1.0.14&quot;</code> 是配置迁移结构常量，不是插件发布版本或 API 坐标。</p><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td><code>/codex</code>、<code>/ecodex</code> 的可用子命令、权限和示例。</td></tr><tr><td><a href="./configuration.html">配置详解</a></td><td><code>config.yml</code>、<code>codex/*.yml</code>、<code>gui/codex_gui.yml</code> 与 <code>lang/*.yml</code> 的入口和版本语义。</td></tr><tr><td><a href="./advancements.html">成就页定义</a></td><td><code>advancements/*.yml</code> 的页面与节点字段、节点 key 规则、坐标规则与完成动作。</td></tr><tr><td><a href="./gui.html">分类条目 GUI</a></td><td><code>codex/*.yml</code> 分类/条目、四态进度、激活与一次性领取、布局 type 和占位符。</td></tr><tr><td><a href="./triggers.html">事件触发器</a></td><td>原版 Advancement 的 <code>triggers.entries</code> 与分类条目的 unlock triggers。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>EmakiCodex 注册到 CoreLib ActionRegistry 的七个动作段。</td></tr><tr><td><a href="./api.html">API 与集成</a></td><td>第三方插件通过 <code>emaki-codex-api</code> 调用原版 Advancement 层的方式。</td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to “核心能力”">​</a></h2><ul><li><strong>原版 Advancement 图鉴</strong>：一个 <code>advancements/*.yml</code> 文件就是一个原版成就标签页，节点 key 形如 <code>emakicodex:&lt;page&gt;/&lt;node&gt;</code>。</li><li><strong>分类条目图鉴</strong>：一个 <code>codex/*.yml</code> 文件定义一个 GUI 分类，条目复合 id 为 <code>&lt;category_id&gt;/&lt;entry_id&gt;</code>，分类按 <code>order</code> 排序。</li><li><strong>四态条目进度</strong>：条目状态依次为未解锁、可激活、已激活、已领取；激活与领取是两个独立操作。</li><li><strong>两条解锁通路</strong>：<code>unlock.triggers</code> 监听共享事件，<code>unlock.advancements</code> 监听原版 Advancement，任一命中即可解锁。</li><li><strong>两类奖励</strong>：<code>rewards.attributes</code> 在激活后按当前配置实时提供属性；<code>rewards.actions</code> 在右键领取时只执行一次。</li><li><strong>手动授予/撤销</strong>：管理员可用 <code>/codex grant</code> 与 <code>/codex revoke</code> 管理在线玩家原版节点进度；<code>admin unlock/reset</code> 管理分类条目状态。</li><li><strong>动作链授予与通知</strong>：其他插件可在 CoreLib Action 中调用五个 Advancement 操作、<code>codex_show_toast</code> 和 <code>codex_broadcast_achievement</code>。</li><li><strong>事件触发器</strong>：原版节点可配置 <code>triggers.entries</code>，分类条目可配置 <code>unlock.triggers</code>，两者使用共享 gameplay 事件与条件。</li><li><strong>完成动作</strong>：原版节点完成后执行 <code>actions.complete</code>；分类条目领取时执行 <code>rewards.actions</code>。</li><li><strong>PacketEvents 坐标通道</strong>：安装 PacketEvents 且开启 <code>advancement.packet_coordinates</code> 时，原版节点 <code>x</code> / <code>y</code> 会写入客户端成就界面位置。</li></ul><h2 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to “文件结构”">​</a></h2><p>服务器运行后，EmakiCodex 主要使用以下文件：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiCodex/</span></span>
<span class="line"><span>├─ config.yml</span></span>
<span class="line"><span>├─ advancements/</span></span>
<span class="line"><span>│  └─ example_page.yml</span></span>
<span class="line"><span>├─ codex/</span></span>
<span class="line"><span>│  └─ example_category.yml</span></span>
<span class="line"><span>├─ gui/</span></span>
<span class="line"><span>│  └─ codex_gui.yml</span></span>
<span class="line"><span>├─ data/</span></span>
<span class="line"><span>│  └─ &lt;player-uuid&gt;.yml</span></span>
<span class="line"><span>└─ lang/</span></span>
<span class="line"><span>   ├─ zh_CN.yml</span></span>
<span class="line"><span>   └─ en_US.yml</span></span></code></pre></div><table tabindex="0"><thead><tr><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>主配置，控制默认资源释放、Advancement 注册、PacketEvents 坐标注入和触发器总开关；<code>version</code> 当前为 <code>1.1.0</code>。</td></tr><tr><td><code>advancements/*.yml</code></td><td>原版成就页配置。每个文件定义一个页面、一个根节点和任意数量子节点。</td></tr><tr><td><code>codex/*.yml</code></td><td>分类条目配置。每个文件定义一个 GUI 分类，条目复合 id 为 <code>&lt;category_id&gt;/&lt;entry_id&gt;</code>。</td></tr><tr><td><code>gui/codex_gui.yml</code></td><td>分类条目 GUI 模板；功能格必须显式写 <code>type</code>。</td></tr><tr><td><code>data/&lt;uuid&gt;.yml</code></td><td>每个玩家的解锁、激活和领取状态；属性数值不写入，按当前分类配置实时推导。</td></tr><tr><td><code>lang/*.yml</code></td><td>命令、GUI、重载和控制台提示文本。</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to “快速开始”">​</a></h2><ol><li>把 <code>EmakiCoreLib-*.jar</code> 与 <code>EmakiCodex-*.jar</code> 放入服务器 <code>plugins/</code>。</li><li>不要把 <code>emaki-codex-api-*.jar</code> 放进服务器 <code>plugins/</code>；API Jar 只给开发者作为编译依赖使用。</li><li>首次启动后查看 <code>plugins/EmakiCodex/advancements/example_page.yml</code>。</li><li>修改或新增成就页后执行：</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex reload</span></span></code></pre></div><ol start="5"><li>打开分类条目图鉴 GUI：</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex codex</span></span></code></pre></div><ol start="6"><li>测试授予原版示例节点：</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex grant Steve example/first_step</span></span></code></pre></div><ol start="7"><li>管理分类条目时使用复合 id：</li></ol><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex admin unlock Steve example/first_blood</span></span>
<span class="line"><span>/codex admin reset Steve example/first_blood</span></span></code></pre></div><p>完整 key 也可写成：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex grant Steve emakicodex:example/first_step</span></span></code></pre></div><h2 id="两套配置模型速览" tabindex="-1">两套配置模型速览 <a class="header-anchor" href="#两套配置模型速览" aria-label="Permalink to “两套配置模型速览”">​</a></h2><p>一个 <code>advancements/*.yml</code> 定义一个原版成就页：</p><ul><li>页面级：<code>page_id</code>（key 路径前缀）、<code>title</code>、<code>background</code>、<code>root</code>。</li><li>节点级：<code>icon</code>、<code>title</code>、<code>description</code>、<code>frame</code>、<code>parent</code>、<code>x</code> / <code>y</code>、<code>toast</code>、<code>announce</code>、<code>hidden</code>。</li><li>节点完成动作写在 <code>actions.complete</code>，事件触发器写在 <code>triggers.entries</code>。</li></ul><p>一个 <code>codex/*.yml</code> 定义一个分类条目页：</p><ul><li>分类级：<code>category_id</code>、<code>title</code>、<code>icon</code>、<code>order</code>、<code>entries</code>。</li><li>条目级：<code>title</code>、<code>description</code>、<code>icon</code>、<code>hidden</code>、<code>unlock.triggers</code>、<code>unlock.advancements</code>、<code>rewards.attributes</code>、<code>rewards.actions</code>。</li><li>条目 id 在命令、GUI 状态和数据文件中使用 <code>&lt;category_id&gt;/&lt;entry_id&gt;</code> 复合形式。</li></ul><p>两类触发条件都使用 CoreLib 标准条件组：<code>condition.type</code> + <code>condition.entries</code>。原版节点会注册为 <code>emakicodex:&lt;page_id&gt;/&lt;node_id&gt;</code>；完整字段见<a href="./advancements.html">成就页定义</a>与<a href="./gui.html">分类条目 GUI</a>。</p><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to “使用提示”">​</a></h2><ul><li>原版 Advancement 与分类条目 GUI 是两套独立状态；不要把 <code>advancements/&lt;page_id&gt;</code> 当作 <code>codex/&lt;category_id&gt;</code> 使用。</li><li>原版节点完成条件统一由 Codex 授予：命令、Action、公开 API 或触发器会奖励内部 <code>codex</code> criterion。</li><li><code>actions.complete</code> 只会在原版节点首次完成时触发；分类条目的 <code>rewards.actions</code> 只会在一次性领取时触发。</li><li>分类条目的 <code>rewards.attributes</code> 不保存数值，按当前配置实时推导；修改奖励配置会影响已激活玩家。</li><li>如果开启原版成就坐标，建议同一成就页全部节点都配置 <code>x</code> / <code>y</code>，避免“部分显式坐标 + 部分自动排布”导致重叠。</li></ul>`,33)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};